/* Risdel Books Module 13 — Purchasing & Procurement. Relational reference for future SQL Server migration. */
IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name='procurement') EXEC('CREATE SCHEMA procurement');
GO
CREATE TABLE procurement.PurchaseRequests (Id uniqueidentifier NOT NULL PRIMARY KEY, RequestNumber nvarchar(30) NOT NULL UNIQUE, WarehouseId uniqueidentifier NOT NULL, RequestType nvarchar(30) NOT NULL, Reason nvarchar(500) NULL, Priority nvarchar(20) NOT NULL, Status nvarchar(30) NOT NULL, RequestedBy uniqueidentifier NULL, RequestedAt datetime2 NOT NULL, SubmittedAt datetime2 NULL, ApprovedAt datetime2 NULL, ApprovedBy uniqueidentifier NULL, RejectedAt datetime2 NULL, RejectedBy uniqueidentifier NULL, RejectionReason nvarchar(500) NULL, Notes nvarchar(max) NULL, IsActive bit NOT NULL DEFAULT 1, CreatedAt datetime2 NOT NULL DEFAULT sysutcdatetime(), UpdatedAt datetime2 NOT NULL DEFAULT sysutcdatetime());
CREATE TABLE procurement.PurchaseRequestLines (Id uniqueidentifier NOT NULL PRIMARY KEY, PurchaseRequestId uniqueidentifier NOT NULL, ProductId uniqueidentifier NOT NULL, WarehouseId uniqueidentifier NOT NULL, QuantityRequested decimal(18,3) NOT NULL, QuantityApproved decimal(18,3) NOT NULL DEFAULT 0, EstimatedUnitCost decimal(18,2) NOT NULL DEFAULT 0, PreferredSupplierId uniqueidentifier NULL, Reason nvarchar(500) NULL, Status nvarchar(30) NOT NULL, IsActive bit NOT NULL DEFAULT 1, CreatedAt datetime2 NOT NULL DEFAULT sysutcdatetime(), CONSTRAINT FK_PRLines_PR FOREIGN KEY(PurchaseRequestId) REFERENCES procurement.PurchaseRequests(Id));
CREATE TABLE procurement.PurchaseOrders (Id uniqueidentifier NOT NULL PRIMARY KEY, PONumber nvarchar(30) NOT NULL UNIQUE, PurchaseRequestId uniqueidentifier NULL, SupplierId uniqueidentifier NOT NULL, WarehouseId uniqueidentifier NOT NULL, OrderDate date NOT NULL, ExpectedDeliveryDate date NULL, Status nvarchar(30) NOT NULL, CurrencyCode nvarchar(3) NOT NULL DEFAULT 'NGN', PaymentTermsDays int NOT NULL DEFAULT 0, Subtotal decimal(18,2) NOT NULL, DiscountAmount decimal(18,2) NOT NULL DEFAULT 0, TaxAmount decimal(18,2) NOT NULL DEFAULT 0, Total decimal(18,2) NOT NULL, Notes nvarchar(max) NULL, SentAt datetime2 NULL, ApprovedAt datetime2 NULL, ApprovedBy uniqueidentifier NULL, ClosedAt datetime2 NULL, IsActive bit NOT NULL DEFAULT 1, CreatedAt datetime2 NOT NULL DEFAULT sysutcdatetime(), UpdatedAt datetime2 NOT NULL DEFAULT sysutcdatetime());
CREATE TABLE procurement.PurchaseOrderLines (Id uniqueidentifier NOT NULL PRIMARY KEY, PurchaseOrderId uniqueidentifier NOT NULL, PurchaseRequestLineId uniqueidentifier NULL, ProductId uniqueidentifier NOT NULL, QuantityOrdered decimal(18,3) NOT NULL, QuantityReceived decimal(18,3) NOT NULL DEFAULT 0, UnitCost decimal(18,2) NOT NULL, DiscountPercent decimal(9,4) NOT NULL DEFAULT 0, TaxAmount decimal(18,2) NOT NULL DEFAULT 0, LineTotal decimal(18,2) NOT NULL, Status nvarchar(30) NOT NULL, IsActive bit NOT NULL DEFAULT 1, CreatedAt datetime2 NOT NULL DEFAULT sysutcdatetime(), CONSTRAINT FK_POLines_PO FOREIGN KEY(PurchaseOrderId) REFERENCES procurement.PurchaseOrders(Id));
GO
